"""Visual money decisions over existing private statement history."""
PLAN_CSS = r'''
.plan-viz-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}.plan-viz{min-width:0;border-top:1px solid var(--line);padding-top:18px}.plan-viz h3{font-size:17px;letter-spacing:-.025em;margin:0 0 8px}.plan-chart{height:255px;position:relative;margin:16px 0}.plan-chart canvas{width:100%!important;height:100%!important}.plan-legend{display:flex;gap:10px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.plan-viz table{border-collapse:collapse;width:100%;font-size:12px}.plan-viz td,.plan-viz th{padding:8px;text-align:left;border-bottom:1px solid var(--line)}.plan-viz details summary{min-height:40px;cursor:pointer;color:var(--blue);font-size:12px}.plan-intro{font-size:14px;line-height:1.7;color:var(--muted)}.plan-form{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}.plan-form label{display:grid;gap:7px;font-size:12px}.plan-form .run{grid-column:1/-1}.plan-callout{padding:18px;border-radius:16px;background:var(--studio-lilac);margin:18px 0;font-size:14px;line-height:1.7}.plan-callout[data-state=gap]{background:var(--review-bg);border-left:3px solid var(--amber)}.plan-status{font-size:12px;color:var(--muted);line-height:1.65}.plan-checks{display:flex;gap:9px;flex-wrap:wrap;font-size:11px;line-height:1.5}.plan-checks span{padding:7px 10px;border-radius:12px;background:var(--studio-mint);color:var(--cyan)}.plan-source{border-top:1px solid var(--line);font-size:12px;line-height:1.7;margin-top:18px;padding-top:16px;color:var(--muted)}.plan-entry{margin-top:18px}.plan-visual-caption{font-size:12px;color:var(--muted);line-height:1.65}.plan-proof{font-size:12px;color:var(--muted);line-height:1.8}.plan-proof summary{cursor:pointer;min-height:42px}.plan-empty{padding:24px 0}.plan-inline-status{font-size:11px!important;line-height:1.6!important;color:var(--blue)!important}
@media(max-width:1100px){.plan-viz-grid{grid-template-columns:1fr}.plan-chart{height:235px}}
@media(max-width:600px){.plan-form{grid-template-columns:1fr}.plan-chart{height:235px}.plan-viz h3{font-size:16px}.plan-viz-grid{gap:14px}}
'''

PLAN_JS = r'''
    {
      const planningView=view('plan','Turn one money goal into checked options. These are editable scenarios, not automatic payments or a forecast.');titles.plan='Make room for what matters';planningView.querySelector('h1').textContent=titles.plan;planningView.setAttribute('aria-label',titles.plan);
      const privacyView=view('privacy','Choose what Friday can use. Statement analysis does not need payment rules or a bank connection.');titles.privacy='Privacy & data';privacyView.querySelector('h1').textContent=titles.privacy;privacyView.setAttribute('aria-label',titles.privacy);
      const privacyIntro=element('p','Google sign-in identifies your private workspace. General questions need no records. Statement totals go to Gemini only when you explicitly share them in chat.','plan-intro');privacyView.append(privacyIntro);
      const shareSettings=element('button','Choose what Friday can use','planner');shareSettings.type='button';shareSettings.addEventListener('click',()=>document.dispatchEvent(new CustomEvent('friday:choose-statement-context')));privacyView.append(shareSettings);
      const cleanup=[...settings.querySelectorAll('section')].find(s=>[...s.querySelectorAll('button')].some(b=>b.textContent==='Delete reviews & drafts'));if(cleanup){cleanup.querySelector('p').textContent='Choose a cleanup age for reviews. Either cleanup action also clears ALL saved statements, diary entries, follow-ups and cash-flow snapshots. Payment receipts and duplicate-payment protection are kept. Read the confirmation before continuing.';privacyView.append(cleanup);}
      document.querySelectorAll('[data-screen-link=settings]').forEach(b=>{if(b.closest('.simple-more'))b.remove();else b.dataset.screenLink='privacy';});
      const statementLabel=$('friday-chat-statements')?.closest('label')?.querySelector('span');if(statementLabel)statementLabel.textContent='Use my saved statement totals for answers and plans · no transaction descriptions';
      const extraContext=everydayAssistant.querySelector('.statement-consent-details summary');if(extraContext)extraContext.textContent='Advanced sources · optional older tools';
      let source=null,lastPlan=null,planBusy=false;const charts=new Map();
      const palette=['#a88ad4','#70af9a','#e9a184','#c2b36b','#8dadd8','#c58ead','#a1b59b','#a8a1be','#d0aa88','#8eaaa6','#b29ab0'];
      const money=n=>scenarioMoney(n);
      function destroyStaleCharts(){for(const [canvas,chart]of charts){if(!canvas.isConnected){chart.destroy();charts.delete(canvas);}}}
      function draw(canvas,type,labels,datasets){destroyStaleCharts();if(typeof Chart==='undefined'){canvas.hidden=true;return;}charts.get(canvas)?.destroy();const dark=document.documentElement.dataset.theme==='dark';const ink=dark?'#f5f1ff':'#26334e';const muted=dark?'#bcb9d3':'#5c6382';
        const options={responsive:true,maintainAspectRatio:false,animation:matchMedia('(prefers-reduced-motion:reduce)').matches||document.documentElement.dataset.motion==='off'?false:{duration:260},plugins:{legend:{display:true,position:'bottom',labels:{color:ink,boxWidth:10,padding:13,font:{size:11}}},tooltip:{callbacks:{label:c=>String(c.dataset.label||c.label)+': '+money(Math.round(c.raw))}}}};
        if(type==='doughnut')options.cutout='68%';else options.scales={x:{grid:{display:false},ticks:{color:muted,font:{size:10}}},y:{grid:{color:dark?'#414059':'#eeecf3'},ticks:{color:muted,font:{size:10},callback:v=>money(v)}}};
        charts.set(canvas,new Chart(canvas,{type,data:{labels,datasets},options}));
      }
      function graphic(title,type,labels,series,caption){const section=element('section',null,'plan-viz');section.append(element('h3',title),element('p',caption,'plan-visual-caption'));const box=element('div',null,'plan-chart');const canvas=element('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label',title+'. Exact amounts are in the table below.');box.append(canvas);section.append(box);
        const details=element('details');details.append(element('summary','Read the exact figures'));const table=element('table');const tr=element('tr');['Category / scenario',...series.map(s=>s.label)].forEach(t=>{const th=element('th',t);th.scope='col';tr.append(th);});const head=element('thead');head.append(tr);table.append(head);const body=element('tbody');labels.forEach((label,i)=>{const row=element('tr');row.append(element('th',label));series.forEach(s=>row.append(element('td',money(s.data[i]))));body.append(row);});table.append(body);details.append(table);section.append(details);
        const datasets=series.map((s,i)=>({...s,borderWidth:type==='line'?2:0,borderRadius:type==='bar'?5:0,backgroundColor:type==='doughnut'?palette:i?'#e9a184':'#70af9a',borderColor:i?'#e9a184':'#70af9a',tension:.2}));section._renderChart=()=>draw(canvas,type,labels,datasets);return section;
      }
      function spendingCharts(data){const parent=views.dashboard.querySelector('.statement-chart-grid');if(!parent||!data.summary.transaction_count)return;parent.querySelector('.plan-viz-grid')?.remove();const grid=element('div',null,'plan-viz-grid');grid.style.gridColumn='1 / -1';const s=data.summary;const pie=graphic('Where your spending went','doughnut',s.categories.map(r=>r.category),[{label:'Spending',data:s.categories.map(r=>r.amount_minor)}],'Reviewed expense categories only. Transfers and repayments are not added as new purchases.');const monthly=graphic('Income and outgoings','bar',s.monthly.map(r=>r.month),[{label:'Identified income',data:s.monthly.map(r=>r.identified_income_minor)},{label:'Spending + loan repayments',data:s.monthly.map(r=>r.spending_minor+r.loan_repayments_minor)}],'Supplied months, not a forecast. Missing accounts or card purchases can understate outgoings.');grid.append(pie,monthly);if(typeof Chart!=='undefined')[...parent.children].forEach(n=>n.hidden=true);parent.prepend(grid);requestAnimationFrame(()=>{pie._renderChart();monthly._renderChart();});
        const next=views.dashboard.querySelector('.statement-next');if(next&&!next.querySelector('[data-screen-link=plan]')){const button=element('button','Build a visual money plan','planner');button.type='button';button.dataset.screenLink='plan';next.append(button);}
      }
      const originalHome=root.renderStudioHome;root.renderStudioHome=function(target,data){originalHome(target,data);source=data;queueMicrotask(()=>spendingCharts(data));if(lastPlan&&(lastPlan.source_revision!==data.revision||lastPlan.workspace_generation!==data.workspace_generation)){lastPlan=null;planResult.replaceChildren(element('p','Your statement history changed. Recalculate before using the old plan.','plan-status'));}if(data.summary.transaction_count){const action=element('button','Make room for a goal','planner plan-entry');action.type='button';action.dataset.screenLink='plan';target.querySelector('.studio-example')?.append(action);}refreshPlanInputs();};
      const planBody=element('div');const planForm=element('form',null,'plan-form');const target=element('input');target.type='text';target.inputMode='decimal';target.value='0.00';target.required=true;target.pattern='(?:0|[1-9][0-9]{0,6})(?:[.][0-9]{1,2})?';const month=element('select');const cap=element('select');const shock=element('select');[[10,'Up to 10%'],[25,'Up to 25%'],[50,'Up to 50%']].forEach(([v,l])=>{const o=element('option',l);o.value=v;cap.append(o);});cap.value='25';[[0,'No drop'],[10,'10% lower income'],[20,'20% lower income'],[30,'30% lower income'],[50,'50% lower income']].forEach(([v,l])=>{const o=element('option',l);o.value=v;shock.append(o);});shock.value='10';
      function formField(label,input){const wrap=element('label',label);wrap.append(input);planForm.append(wrap);}formField('Monthly reduction to explore · INR',target);formField('Source month · completeness not established',month);formField('Maximum cut in an adjustable category',cap);formField('Stress-test assumption',shock);
      const calculate=element('button','Calculate my options','run');calculate.type='submit';planForm.append(calculate);const planStatus=element('p','No plan has been calculated. Nothing is saved or paid.','plan-status');planStatus.setAttribute('role','status');const planResult=element('div');planBody.append(element('p','Protect essentials. Explore a goal. See what changes if income falls. Every figure is calculated from the selected month and your editable assumptions.','plan-intro'),planForm,planStatus,planResult);planningView.append(planBody);
      let protectedChoices=[],preferred=[];
      function refreshPlanInputs(){if(!source)return;const selection=month.value;month.replaceChildren();source.summary.monthly.forEach(r=>{const o=element('option',r.month);o.value=r.month;month.append(o);});month.value=[...month.options].some(o=>o.value===selection)?selection:month.lastElementChild?.value||'';planForm.hidden=!source.summary.transaction_count;if(!source.summary.transaction_count){planStatus.replaceChildren(element('span','Add and save a reviewed statement first. '));const start=element('button','Add a statement','planner');start.type='button';start.dataset.screenLink='statements';planStatus.append(start);}else if(!lastPlan)planStatus.textContent='Scenario only. Essentials and recorded loan repayments stay protected. No amount is a live bank balance.';}
      function renderPlan(p){if(p.scope!=='STATEMENT_COUNTERFACTUAL_PLAN'||p.money_moved!==false||p.payment_authorized!==false||!p.checks||['exact_reduction','within_caps','essentials_unchanged','marginal_optimality'].some(k=>p.checks[k]!==true))throw new Error('Plan checks did not pass');if(source&&(p.source_revision!==source.revision||p.workspace_generation!==source.workspace_generation))throw new Error('Statement revision changed');lastPlan=p;target.value=p.assumptions.target_reduction_inr;if(![...cap.options].some(o=>o.value===String(p.assumptions.max_cut_percent))){const o=element('option','Up to '+p.assumptions.max_cut_percent+'%');o.value=p.assumptions.max_cut_percent;cap.append(o);}cap.value=String(p.assumptions.max_cut_percent);if(![...shock.options].some(o=>o.value===String(p.assumptions.income_drop_percent))){const o=element('option',p.assumptions.income_drop_percent+'% lower income');o.value=p.assumptions.income_drop_percent;shock.append(o);}shock.value=String(p.assumptions.income_drop_percent);month.value=p.source_month;protectedChoices=p.assumptions.protected_categories;preferred=p.assumptions.prefer_to_reduce;planResult.replaceChildren();
        const callout=element('div',null,'plan-callout');callout.dataset.state=p.unmet_target_minor?'gap':'checked';callout.append(element('b',p.unmet_target_minor?'The goal needs a different approach.':'The requested reduction fits the entered limits.'),element('p','Requested '+money(p.target_reduction_minor)+' · allocated '+money(p.achievable_reduction_minor)+(p.unmet_target_minor?' · still unmet '+money(p.unmet_target_minor):'')+'. These are scenario reductions, not money already saved.'));planResult.append(callout);
        const checks=element('div',null,'plan-checks');['Essentials protected','Category caps respected','Exact totals checked','No financial action'].forEach(s=>checks.append(element('span',s)));planResult.append(checks);if(p.assumptions.protected_categories.length)planResult.append(element('p','Also protected by your request: '+p.assumptions.protected_categories.join(', ')+'.','plan-status'));if(p.assumptions.prefer_to_reduce.length)planResult.append(element('p','Preferred adjustable categories: '+p.assumptions.prefer_to_reduce.join(', ')+'. These are editable scenario preferences, not advice to cut essential costs.','plan-status'));
        const grid=element('div',null,'plan-viz-grid');const beforeAfter=graphic('What would change','bar',p.categories.map(r=>r.category),[{label:'Source month',data:p.categories.map(r=>r.before_minor)},{label:'Scenario',data:p.categories.map(r=>r.after_minor)}],'Protected categories have the same amount in both bars. Other cuts stay within the chosen cap.');grid.append(beforeAfter);let stress=null;if(p.income_comparison_available){stress=graphic('If income is lower','line',p.stress_scenarios.map(r=>r.income_drop_percent+'% drop'),[{label:'Before changes',data:p.stress_scenarios.map(r=>r.before_margin_minor)},{label:'After changes',data:p.stress_scenarios.map(r=>r.after_margin_minor)}],'Income less classified spending and loan repayments. A negative value is a gap in these assumptions, not a predicted bank overdraft.');grid.append(stress);}else grid.append(element('p','Income comparison unavailable: no income was identified in this source month. Missing income is not proof of zero earnings. Review your statements and labels before making an income-based plan.','plan-source'));planResult.append(grid);
        const exact=element('p',p.income_comparison_available?'Source-month margin '+money(p.baseline_margin_minor)+' → scenario margin '+money(p.planned_margin_minor)+'. At '+p.assumptions.income_drop_percent+'% lower income: '+money(p.stress_margin_minor)+'. These margins are not disposable cash or guaranteed savings.':'Identified spending and loan repayments '+money(p.baseline_outgoings_minor)+' → scenario '+money(p.planned_outgoings_minor)+'. No income or affordability conclusion is available.','plan-source');planResult.append(exact);
        const proof=element('details',null,'plan-proof');proof.append(element('summary','How Friday checked this plan'));proof.append(element('p','Gemini can interpret your goal. The independent integer allocation engine calculates category cuts, then verifies protected spending, caps, conservation and marginal-cost optimality. Preference weights are proposed assumptions, not trained financial advice. Source revision '+p.source_revision+' · '+p.source_month+'.'));
        const list=element('ul');p.limits.concat(p.warnings).forEach(s=>list.append(element('li',s)));proof.append(list);planResult.append(proof);planStatus.textContent='Plan calculated · '+(p.proposal_source==='GEMINI_TYPED_GOAL'?'Gemini interpreted the goal; ':'')+'exact engine checked the numbers. Not saved or executed.';requestAnimationFrame(()=>{beforeAfter._renderChart();stress?._renderChart();});
      }
      planForm.addEventListener('submit',async e=>{e.preventDefault();if(planBusy||!source)return;planBusy=true;calculate.disabled=true;planForm.setAttribute('aria-busy','true');planStatus.textContent='Calculating bounded options against your current statement revision…';try{const p=await jsonRequest('/api/friday/plans/preview','POST',{target_reduction_inr:target.value.trim(),protected_categories:protectedChoices,prefer_to_reduce:preferred,max_cut_percent:Number(cap.value),income_drop_percent:Number(shock.value),month:month.value,expected_revision:source.revision,workspace_generation:source.workspace_generation});renderPlan(p);}catch(error){planStatus.textContent='Could not calculate this plan. '+error.message+' Reload Spending if your history changed.';}finally{planBusy=false;calculate.disabled=false;planForm.setAttribute('aria-busy','false');}});
      document.addEventListener('friday:assistant-analysis',event=>{const r=event.detail;try{if(r.money_plan){renderPlan(r.money_plan);show('plan');}else if(r.statement_visuals){show('dashboard');}}catch{planStatus.textContent='The proposed plan did not pass its display checks. No action was performed.';}});
      document.addEventListener('friday:cashflow-cleared',()=>{lastPlan=null;source=null;planResult.replaceChildren();planStatus.textContent='Private inputs were cleared. Add a statement to start again.';});
      const oldShow=show;show=function(name,push=true){oldShow(name==='settings'?'privacy':name,push);if(active==='plan'||active==='privacy'){root.dataset.wide='false';const dock=root.querySelector('.studio-chat-dock');dock.hidden=false;dock.append(everydayAssistant);}if(active==='plan'){refreshPlanInputs();if(!source)jsonRequest('/api/friday/statements').then(data=>{source=data;refreshPlanInputs();}).catch(()=>{planStatus.textContent='Saved statements are unavailable. No plan was guessed.';});}if(active==='privacy'){jsonRequest('/api/friday/privacy').then(p=>{const retention=privacyView.querySelector('select');if(retention)retention.value=p.retention_days?String(p.retention_days):'';}).catch(()=>{});}if(active==='dashboard'&&source)queueMicrotask(()=>spendingCharts(source));};
      new MutationObserver(()=>{for(const canvas of charts.keys()){const section=canvas.closest('.plan-viz');if(canvas.isConnected)section?._renderChart();}}).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme','data-motion']});
    }
'''
